create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),name text not null,email text unique not null,password_hash text not null,avatar_url text,created_at timestamptz default now());
create table if not exists albums(id uuid primary key default gen_random_uuid(),owner_id uuid not null references users(id) on delete cascade,name text not null,description text default '',event_date date,location text default '',cover_url text,created_at timestamptz default now());
create table if not exists album_members(album_id uuid references albums(id) on delete cascade,user_id uuid references users(id) on delete cascade,role text not null default 'member',joined_at timestamptz default now(),primary key(album_id,user_id));
create table if not exists memories(id uuid primary key default gen_random_uuid(),album_id uuid not null references albums(id) on delete cascade,user_id uuid not null references users(id) on delete cascade,story text default '',created_at timestamptz default now());
create table if not exists media(id uuid primary key default gen_random_uuid(),memory_id uuid not null references memories(id) on delete cascade,media_type text not null check(media_type in ('image','video')),media_url text not null,file_name text,created_at timestamptz default now());
create table if not exists voice_memories(id uuid primary key default gen_random_uuid(),memory_id uuid not null references memories(id) on delete cascade,audio_url text not null,created_at timestamptz default now());
create table if not exists songs(id uuid primary key default gen_random_uuid(),memory_id uuid not null references memories(id) on delete cascade,title text,song_url text not null,created_at timestamptz default now());
create table if not exists comments(id uuid primary key default gen_random_uuid(),memory_id uuid not null references memories(id) on delete cascade,user_id uuid not null references users(id) on delete cascade,text text not null,created_at timestamptz default now());
create table if not exists reactions(memory_id uuid references memories(id) on delete cascade,user_id uuid references users(id) on delete cascade,reaction text not null default '❤️',created_at timestamptz default now(),primary key(memory_id,user_id));
create table if not exists invitations(id uuid primary key default gen_random_uuid(),album_id uuid not null references albums(id) on delete cascade,invited_by uuid not null references users(id) on delete cascade,token text unique not null,created_at timestamptz default now());
create index if not exists idx_memories_album on memories(album_id);
create index if not exists idx_media_memory on media(memory_id);
